gn:right;\">{{premiersPas}}</td></tr>\n</table>\n<h2 style=\"margin:28px 0 10px;font-size:18px;line-height:1.3;color:#0b0b0c;\">Membres absents depuis plus d’un mois</h2>\n<p style=\"margin:0 0 14px;\">Un appel personnel de l’accueil fait souvent la différence :</p>\n{{{comebackHtml}}}\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"margin:28px 0 10px;\"><tr><td style=\"border-radius:8px;background:#E10600;\"><a href=\"{{adminUrl}}\" style=\"display:inline-block;padding:14px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;border-radius:8px;\">Ouvrir l’administration</a></td></tr></table>\n          </td>\n        </tr>\n        <tr>\n          <td class=\"px\" style=\"background:#0b0b0c;padding:26px 32px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#bdbdbd;\">\n            <strong style=\"color:#ffffff;font-size:13px;letter-spacing:1px;\">MELIORA GYM</strong><br>\n            {{address}}{{#if phone}} · {{phone}}{{/if}}<br>\n            <a href=\"{{instagramUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Instagram {{instagramHandle}}</a>\n            &nbsp;·&nbsp; <a href=\"{{facebookUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Facebook</a>\n            &nbsp;·&nbsp; <a href=\"{{mapsUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Itinéraire</a>\n            &nbsp;·&nbsp; <a href=\"{{websiteUrl}}\" style=\"color:#ffffff;text-decoration:underline;\">Site web</a>\n            {{#if footerNote}}<p style=\"margin:14px 0 0;color:#8c8c8c;\">{{footerNote}}</p>{{/if}}\n            <p style=\"margin:14px 0 0;color:#6f6f6f;\">© {{year}} Meliora Gym — Sousse, Tunisie</p>\n          </td>\n        </tr>\n      </table>\n    </td>\n  </tr>\n</table>\n</body>\n</html>\n"};

